<script setup lang="ts">
import {ref,onMounted} from 'vue';import {useBusinessStore,businessApi} from '../stores/business';import {t as tr} from '../i18n';import UiIcon from '../components/UiIcon.vue';import type {Target} from '@shared/labops-targets.js';
const business=useBusinessStore(),emit=defineEmits<{logout:[];navigate:[Target]}>(),error=ref(''),busy=ref(false),preference=ref<{enabled:boolean;quietStart:string;quietEnd:string;maxPerDay:number;maxPerEvent:number;minIntervalMinutes:number;categories:string[]}>();
onMounted(async()=>{try{preference.value=(await businessApi<{preference:typeof preference.value}>('proxy/reminder-preferences')).preference;}catch(e){error.value=(e as Error).message;}});
async function save(){if(!preference.value||busy.value)return;busy.value=true;try{await businessApi('proxy/reminder-preferences',{...preference.value,scopeKey:business.scopeKey});error.value='本人提醒偏好已保存到主系统';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section class="mobile-section"><h2>{{business.profile?.username}}</h2><p>{{tr("身份：")}}{{tr(business.profile?.identity==='admin'?'管理员':'志愿者')}}{{business.profile?.className?' · '+business.profile.className:''}}</p></section><nav class="mobile-more-links" :aria-label="tr('更多')"><button v-for="item in [{view:'settings',label:'设置',icon:'settings'},{view:'automation',label:'自动化',icon:'clock'},{view:'messages',label:'消息中心',icon:'chat'},{view:'evidence',label:'资料与证据',icon:'evidence'}]" :key="item.view" @click="emit('navigate',{view:item.view})"><UiIcon :name="item.icon"/><span>{{tr(item.label)}}</span><UiIcon name="chevron" :size="14"/></button></nav><details class="mobile-section mobile-reminder-settings"><summary>{{tr('本人站内提醒偏好')}}</summary><form v-if="preference" class="mobile-section mobile-form" @submit.prevent="save"><h3>{{tr("本人站内提醒偏好")}}</h3><label class="mobile-check"><input v-model="preference.enabled" type="checkbox">{{tr("启用站内提醒")}}</label><label>{{tr("静默开始")}}<input v-model="preference.quietStart" type="time"></label><label>{{tr("静默结束")}}<input v-model="preference.quietEnd" type="time"></label><label>{{tr("每日上限")}}<input v-model.number="preference.maxPerDay" type="number" min="1" max="50"></label><label>{{tr("同一依据最多提醒次数")}}<input v-model.number="preference.maxPerEvent" type="number" min="1" max="20"></label><label>{{tr("最短间隔（分钟）")}}<input v-model.number="preference.minIntervalMinutes" type="number" min="0" max="1440"></label><button :disabled="busy">{{tr("保存本人偏好")}}</button><button type="button" @click="emit('navigate',{view:'automation'})">{{tr("设置模板分类与规则")}}</button></form></details><p v-if="error" role="status">{{error}}</p><details class="mobile-section"><summary>{{tr("帮助与安装")}}</summary><p>{{tr("使用浏览器菜单“添加到主屏幕”可保留独立移动端入口。站内提醒以服务端记录为准，当前没有系统推送能力。")}}</p><p>{{tr("离线时保留当前输入；恢复后刷新会话或同一方案编号。保存失败时先保留回答，不会自动重发或重复办理。")}}</p><p>{{tr("聊天会话只查询；正式办理请新建工作会话或进入实验室工作台。删除对话不撤销已提交业务。")}}</p><p>LabOps 1.0.4.0 · Asia/Shanghai</p></details><button class="mobile-danger" @click="emit('logout')">{{tr("退出登录")}}</button></template>
